package io.rift.cronos;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.io.*;import java.util.*;
/** Executed JVM coordinator/CAS tests. Repository/RPC fake; SQLite and Android remain separate gates. */
public final class DiscoveryIndexTest {
 static final String OWNER=TransferDiscoveryTest.OWNER,CONTRACT=TransferDiscoveryTest.CONTRACT,SOURCE="00000000-0000-4000-8000-000000000001",OTHER="00000000-0000-4000-8000-000000000002";
 static final class Repo implements DiscoveryIndex.Repository {long revision;JSONObject state;boolean race,dropAfterCommit;
 public DiscoveryIndex.Snapshot load(String scope)throws Exception{return new DiscoveryIndex.Snapshot(revision,state==null?null:new JSONObject(state.toString()));}
 public boolean commit(String scope,long expected,JSONObject value)throws Exception{if(race){race=false;revision++;return false;}if(expected!=revision)return false;state=value==null?null:new JSONObject(value.toString());revision++;if(dropAfterCommit){dropAfterCommit=false;state=null;revision++;}return true;}}
 static final class Rpc implements TransferDiscovery.Rpc {int calls,anchors;boolean fail;int reorgAfter=Integer.MAX_VALUE;String hash=TransferDiscoveryTest.HASH;JSONArray incoming=new JSONArray();
 public void requireCronos(){calls++;}public Object call(String method,JSONArray params)throws Exception{calls++;if(method.equals("eth_blockNumber"))return "0x70";if(method.equals("eth_getBlockByNumber")){anchors++;return new JSONObject().put("number",params.getString(0)).put("hash",anchors>reorgAfter?"0x"+"f".repeat(64):hash);}if(method.equals("eth_getLogs")){if(fail)throw new IOException("Fixture provider failure");JSONArray topics=params.getJSONObject(0).getJSONArray("topics");return topics.length()==3?incoming:new JSONArray();}throw new AssertionError(method);}}
 static JSONObject start(Repo repo)throws Exception{Rpc rpc=new Rpc();rpc.incoming.put(TransferDiscoveryTest.log("ERC-721",true,1));return DiscoveryIndex.advance(repo,rpc,OWNER,CONTRACT,"ERC-721",SOURCE,repo.revision,true,"100","10",1000,()->{});}
 static JSONObject resume(Repo repo,Rpc rpc)throws Exception{return DiscoveryIndex.advance(repo,rpc,OWNER,CONTRACT,"ERC-721",SOURCE,repo.revision,false,"recent","10",1001,()->{});}
 @Test public void startResumePersistContinuousHintsAndOverlap()throws Exception{Repo repo=new Repo();JSONObject a=start(repo);assertTrue(a.getBoolean("checkpointVerifiedNow"));assertEquals("109",a.getString("endBlock"));assertEquals(1,a.getInt("candidateCount"));Rpc rpc=new Rpc();rpc.incoming.put(TransferDiscoveryTest.log("ERC-721",true,2).put("blockNumber","0x65"));JSONObject b=resume(repo,rpc);assertEquals("101",b.getString("lastPageFrom"));assertEquals("110",b.getString("endBlock"));assertEquals(2,b.getInt("candidateCount"));assertEquals(2,repo.revision);assertEquals(2,b.getInt("pages"));}
 @Test public void staleRevisionRefusesBeforeNetwork()throws Exception{Repo repo=new Repo();start(repo);Rpc rpc=new Rpc();try{DiscoveryIndex.advance(repo,rpc,OWNER,CONTRACT,"ERC-721",SOURCE,0,false,"recent","10",1001,()->{});fail("stale action accepted");}catch(IOException expected){}assertEquals(0,rpc.calls);assertEquals(1,repo.revision);}
 @Test public void commitRaceCannotOverwriteExistingCheckpoint()throws Exception{Repo repo=new Repo();start(repo);String before=repo.state.toString();repo.race=true;try{resume(repo,new Rpc());fail("racing write accepted");}catch(IOException expected){}assertEquals(before,repo.state.toString());assertEquals(2,repo.revision);}
 @Test public void settingsRevisionChangeInvalidatesWithoutRpc()throws Exception{Repo repo=new Repo();start(repo);Rpc rpc=new Rpc();JSONObject value=DiscoveryIndex.advance(repo,rpc,OWNER,CONTRACT,"ERC-721",OTHER,repo.revision,false,"recent","10",1001,()->{});assertEquals(0,rpc.calls);assertEquals("source-changed",value.getString("status"));assertEquals(0,value.getJSONArray("candidates").length());assertEquals("invalidated",repo.state.getString("status"));assertEquals(0,repo.state.getJSONArray("tokenIds").length());}
 @Test public void previousAnchorMismatchInvalidatesAndClearsNativeHints()throws Exception{Repo repo=new Repo();start(repo);Rpc rpc=new Rpc();rpc.hash="0x"+"f".repeat(64);JSONObject value=resume(repo,rpc);assertEquals("invalidated",value.getString("status"));assertEquals(0,value.getInt("candidateCount"));assertEquals(1,rpc.anchors);}
 @Test public void previousAnchorChangedAfterScanInvalidatesRatherThanAdvancing()throws Exception{Repo repo=new Repo();start(repo);Rpc rpc=new Rpc();rpc.reorgAfter=3;JSONObject value=resume(repo,rpc);assertEquals("invalidated",value.getString("status"));assertEquals("109",repo.state.getString("endBlock"));assertEquals(0,repo.state.getJSONArray("tokenIds").length());}
 @Test public void providerFailureRetainsPriorCheckpoint()throws Exception{Repo repo=new Repo();start(repo);String before=repo.state.toString();Rpc rpc=new Rpc();rpc.fail=true;try{resume(repo,rpc);fail("failed page accepted");}catch(IOException expected){}assertEquals(before,repo.state.toString());assertEquals(1,repo.revision);}
 @Test public void idCapFailureRollsBackProgressAndViewsPaginateWithoutSecrets()throws Exception{Repo repo=new Repo();start(repo);JSONArray ids=new JSONArray();for(int i=0;i<1000;i++)ids.put(Integer.toString(i));repo.state.put("tokenIds",ids);JSONObject first=DiscoveryIndex.view(repo,OWNER,CONTRACT,"ERC-721",SOURCE,0),last=DiscoveryIndex.view(repo,OWNER,CONTRACT,"ERC-721",SOURCE,800);assertEquals(200,first.getJSONArray("candidates").length());assertEquals("200",first.getString("nextOffset"));assertTrue(last.isNull("nextOffset"));assertFalse(first.toString().contains(SOURCE));assertEquals(0,DiscoveryIndex.view(repo,OWNER,CONTRACT,"ERC-721",OTHER,0).getInt("candidateCount"));Rpc rpc=new Rpc();rpc.incoming.put(TransferDiscoveryTest.log("ERC-721",true,1000).put("blockNumber","0x65"));try{resume(repo,rpc);fail("ID overflow accepted");}catch(IOException expected){}assertEquals("109",repo.state.getString("endBlock"));assertEquals(1,repo.revision);}
 @Test public void cancellationBeforeCommitDoesNotPersistAndDeletionPreventsStaleResurrection()throws Exception{Repo repo=new Repo();final int[] calls={0};try{DiscoveryIndex.advance(repo,new Rpc(),OWNER,CONTRACT,"ERC-721",SOURCE,0,true,"100","10",1000,()->{if(++calls[0]>1)throw new IOException("cancelled");});fail("cancelled write");}catch(IOException expected){}assertNull(repo.state);assertEquals(0,repo.revision);start(repo);DiscoveryIndex.remove(repo,OWNER,CONTRACT,"ERC-721",SOURCE,repo.revision,()->{});assertNull(repo.state);assertFalse(repo.commit(DiscoveryIndex.scope(OWNER,CONTRACT,"ERC-721"),1,new JSONObject()));}
 @Test public void existingIndexCannotBeSilentlyReplacedAndInvalidatedCannotResume()throws Exception{Repo repo=new Repo();start(repo);Rpc rpc=new Rpc();try{DiscoveryIndex.advance(repo,rpc,OWNER,CONTRACT,"ERC-721",SOURCE,repo.revision,true,"0","10",1001,()->{});fail("replacement accepted");}catch(IOException expected){}assertEquals(0,rpc.calls);repo.state.put("status","invalidated");try{resume(repo,rpc);fail("invalidated resumed");}catch(IOException expected){}assertEquals(0,rpc.calls);}
 @Test public void concurrentDeletionAfterCommitIsNotReportedAsFreshCheckpoint()throws Exception{Repo repo=new Repo();repo.dropAfterCommit=true;JSONObject result=start(repo);assertFalse(result.getBoolean("exists"));assertFalse(result.getBoolean("checkpointVerifiedNow"));assertEquals(0,result.getInt("candidateCount"));}

}
